/**
 * Global and route IP list precedence parity with the reference engine
 * (guard_core/_utils/access_control.py `_check_ip_lists_detail`,
 * guard_core/core/checks/helpers.py `check_route_ip_access`): when a whitelist
 * is configured only the whitelist decides and the blacklist is not consulted;
 * the blacklist applies only when no whitelist is configured. The expectations
 * in ip-list-precedence-cases.json are generated by running the reference.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { isIpAllowed } from '../../src/utils.js';
import { checkIpAccess } from '../../src/core/checks/ip-access.js';
import { checkRouteIpAccess } from '../../src/core/checks/helpers.js';
import { SecurityConfigSchema } from '../../src/models/config.js';
import { RouteConfig } from '../../src/models/route-config.js';
import { createMockMiddleware } from '../helpers.js';

interface Row {
  whitelist: string[];
  blacklist: string[];
  ip: string;
  global: boolean;
  isAllowed: boolean;
  route: boolean | null;
}

const ROWS: Row[] = JSON.parse(
  readFileSync(new URL('./ip-list-precedence-cases.json', import.meta.url), 'utf8'),
);

function cfg(row: Row) {
  return SecurityConfigSchema.parse({
    enableRedis: false,
    whitelist: row.whitelist.length > 0 ? row.whitelist : null,
    blacklist: row.blacklist,
  });
}

const label = (r: Row) => `wl=${JSON.stringify(r.whitelist)} bl=${JSON.stringify(r.blacklist)} ip=${r.ip}`;

describe('IP list precedence matches the reference', () => {
  it.each(ROWS.map((r) => [label(r), r] as const))('global checkIpAccess %s', async (_l, r) => {
    expect((await checkIpAccess(r.ip, cfg(r))).allowed).toBe(r.global);
  });

  it.each(ROWS.filter((r) => r.ip !== 'unknown').map((r) => [label(r), r] as const))(
    'isIpAllowed %s',
    async (_l, r) => {
      expect(await isIpAllowed(r.ip, cfg(r))).toBe(r.isAllowed);
    },
  );

  it.each(ROWS.filter((r) => r.ip !== 'unknown').map((r) => [label(r), r] as const))(
    'route checkRouteIpAccess %s',
    async (_l, r) => {
      const rc = new RouteConfig();
      rc.ipWhitelist = r.whitelist.length > 0 ? r.whitelist : null;
      rc.ipBlacklist = r.blacklist.length > 0 ? r.blacklist : null;
      expect(await checkRouteIpAccess(r.ip, rc, createMockMiddleware())).toBe(r.route);
    },
  );
});
